  --primary-text: #ffffff;
  --danger: #d92d20;
  --danger-hover: #b42318;
  --danger-bg: #fef3f2;
  --focus: #2b59ff;
  --shadow-sm: 0 1px 2px rgba(15, 23, 41, 0.06), 0 1px 3px rgba(15, 23, 41, 0.08);
  --shadow-lg: 0 20px 40px -12px rgba(15, 23, 41, 0.25), 0 8px 16px -8px rgba(15, 23, 41, 0.1);
  --radius: 12px;
  --radius-sm: 8px;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 24px;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--text);
  color: #fff;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 8px; }

/* Header */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding-top: 16px;
  padding-bottom: 16px;
  flex-wrap: wrap;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  color: var(--text);
  text-decoration: none;
  font-size: 1.05rem;
}
.brand__mark {
  width: 26px; height: 26px;
  border-radius: 8px;
  background: linear-gradient(135deg, #2b59ff 0%, #8a3ffc 100%);
  display: inline-block;
}
.nav {
  display: flex;
  gap: 8px;
  list-style: none;
  margin: 0; padding: 0;
}
.nav a {
  display: inline-block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
}
.nav a:hover { color: var(--text); background: var(--bg); }
.nav a[aria-current="page"] { color: var(--text); background: var(--bg); }

/* Breadcrumb */
.breadcrumb { margin: 24px 0 8px; font-size: 0.875rem; color: var(--text-muted); }
.breadcrumb ol {
  display: flex; flex-wrap: wrap;
  gap: 6px; list-style: none; margin: 0; padding: 0;
}
.breadcrumb li + li::before {
  content: "/";
  margin-right: 6px;
  color: var(--border);
}
.breadcrumb a { color: var(--text-muted); text-decoration: none; }
.breadcrumb a:hover { color: var(--text); text-decoration: underline; }
.breadcrumb [aria-current="page"] { color: var(--text); }

/* Preview card */
.preview {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  margin: 16px 0 48px;
  box-shadow: var(--shadow-sm);
}
.preview__title {
  font-size: 1.625rem;
  font-weight: 700;
  margin: 0 0 4px;
  letter-spacing: -0.01em;
}
.preview__meta {
  margin: 0 0 20px;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.preview__figure { margin: 0 0 20px; }
.preview__image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 540px;
  object-fit: cover;
  border-radius: var(--radius-sm);
  background: #eaecf0;
}
.preview__caption {
  margin-top: 12px;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.preview__actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  padding-top: 8px;
  border-top: 1px solid var(--border);
  margin-top: 8px;
  padding-top: 20px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font: inherit;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 10px 16px;
  min-height: 40px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease, box-shadow 120ms ease;
}
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.btn__icon { flex: none; }

.btn--secondary {
  background: var(--surface);
  color: var(--text);
  border-color: var(--border);
}
.btn--secondary:hover { background: var(--bg); }

.btn--danger {
  background: var(--surface);
  color: var(--danger);
  border-color: var(--border);
}
.btn--danger:hover {
  background: var(--danger-bg);
  border-color: #fecdca;
  color: var(--danger-hover);
}

.dialog__actions .btn--danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.dialog__actions .btn--danger:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

/* Dialog */
.dialog {
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-lg);
  max-width: min(440px, calc(100vw - 32px));
  width: 100%;
}
.dialog::backdrop {
  background: rgba(15, 23, 41, 0.5);
  backdrop-filter: blur(2px);
}
.dialog[open] {
  animation: dialog-in 160ms ease-out;
}
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[open] { animation: none; }
}

.dialog__form {
  margin: 0;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.dialog__title {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.005em;
}
.dialog__body {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
  flex-wrap: wrap;
}

/* Forced colors */
@media (forced-colors: active) {
  .btn { border-color: ButtonText; }
  .btn:focus-visible { outline-color: Highlight; }
  .dialog { border: 1px solid CanvasText; }
  .brand__mark { forced-color-adjust: none; }
}

/* Reflow */
@media (max-width: 480px) {
  .preview { padding: 20px; }
  .preview__title { font-size: 1.35rem; }
  .preview__actions .btn { flex: 1 1 auto; }
  .dialog__actions { flex-direction: column-reverse; }
  .dialog__actions .btn { width: 100%; }
}
